"""BOLEM v3: static pages from the existing catalogue; never edits v1/v2."""
import argparse, json, re, html, pathlib, shutil
from urllib.parse import quote
P=argparse.ArgumentParser();P.add_argument('--repo',default=str(pathlib.Path(__file__).resolve().parents[2]));P.add_argument('--out');args=P.parse_args()
ROOT=pathlib.Path(args.repo); OUT=pathlib.Path(args.out) if args.out else ROOT/'v3'
D=json.loads((ROOT/'_data/catalogo.json').read_text(encoding='utf-8')); PRODUCTS=D['productos']; BYID={p['id']:p for p in PRODUCTS}; CATS=D['categorias']; N=len(PRODUCTS)
E=lambda s:html.escape(str(s),quote=True)
M=lambda v:('$'+f'{v:.2f}').removesuffix('.00')
WA='https://wa.me/50368590899?text='
def wa(s):return WA+quote(s)
HELLO=wa('Hola, vi la colección de BOLEM y quisiera asesoría.')
ARROW='<span aria-hidden="true">↗</span>'
def photo(p,base='',size='card',index=0,eager=False):
 f=p['fotos'][index];stem=f[:-5]; path=base+'../assets/productos/'
 return f'<img src="{path}{stem}-800.webp" srcset="{path}{stem}-480.webp 480w, {path}{stem}-800.webp 800w, {path}{f} 1200w" sizes="{("(max-width: 700px) 90vw, 45vw" if size=="hero" else "(max-width: 700px) 46vw, 24vw")}" width="800" height="1200" alt="{E(p.get("alt",p["nombre"]))}" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""}>'
def card(p,base='',i=0):
 return f'''<article class="product-card" data-category="{p['categoria']}" data-sizes="{E('|'.join(p['tallas']))}" data-price="{p['precio']}" data-index="{i}" data-name="{E(p['nombre'])}"><a class="product-photo" href="{base}prendas/{p['id']}">{photo(p,base)}<span class="photo-link">Ver prenda {ARROW}</span>{'<span class="sold">Agotada</span>' if p.get('agotada') else ''}</a><div class="product-line"><h3><a href="{base}prendas/{p['id']}">{E(p['nombre'])}</a></h3><span class="price">{M(p['precio'])}</span></div><p class="product-meta">{' · '.join(p['tallas'])}{f' <span> / {p["colores"]} colores</span>' if p['colores']>1 else ''}</p></article>'''
def chips(base=''):
 return ''.join(f'<a href="{base}coleccion/?categoria={k}">{E(c["etiqueta"])} <span>{sum(p["categoria"]==k for p in PRODUCTS)}</span>{ARROW}</a>' for k,c in CATS.items())
def shell(title,content,base='',active='',description='',schema=None):
 nav=''.join(f'<a href="{base}{url}" {"aria-current=page" if active==key else ""}>{label}</a>' for key,url,label in [('col','coleccion/','Colección'),('size','tallas','Tu talla'),('about','nosotras','Nosotras'),('blog','blog/','Diario')])
 return f'''<!doctype html><html lang="es-SV"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#FFFDF9"><title>{E(title)} — BOLEM</title><meta name="description" content="{E(description or 'Moda plus size elegida por Mónica. Tallas XL a 4XL, asesoría personal y pedidos por WhatsApp en El Salvador.')}"><link rel="icon" href="{base}ui/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{base}ui/style.css"><link rel="stylesheet" href="{base}ui/fonts.css"><script src="{base}ui/app.js" defer></script>{'<script type="application/ld+json">'+json.dumps(schema,ensure_ascii=False).replace('</','<\\/')+'</script>' if schema else ''}</head><body><a class="skip" href="#main">Saltar al contenido</a><div class="announcement">De El Salvador, para vos. <span>Envíos a todo el país · desde $3.50</span></div><header class="site-header"><a class="wordmark" href="{base or './'}" aria-label="BOLEM — inicio">BOL<span>E</span>M<span class="brand-dot" aria-hidden="true"></span></a><nav class="desktop-nav" aria-label="Principal">{nav}</nav><a class="header-wa" href="{HELLO}" target="_blank" rel="noopener">Hablemos {ARROW}</a><button class="menu-toggle" aria-controls="mobile-nav" aria-expanded="false">Menú <span aria-hidden="true">☰</span></button><nav id="mobile-nav" hidden aria-label="Navegación móvil">{nav}<a href="{HELLO}" target="_blank" rel="noopener">Escribinos por WhatsApp {ARROW}</a></nav></header><main id="main">{content}</main><footer class="site-footer"><div class="footer-top"><div><p class="eyebrow">SEGUIMOS EN CONTACTO</p><h2>Hay más de BOLEM<br><em>por descubrir.</em></h2><a class="text-link" href="https://instagram.com/bolem_sv" target="_blank" rel="noopener">Seguinos en @bolem_sv {ARROW}</a></div><div class="footer-links"><a href="{base}coleccion/">Colección</a><a href="{base}tallas">Guía de tallas</a><a href="{base}nosotras">Nuestra historia</a><a href="{base}blog/">Diario BOLEM</a></div><div class="footer-links"><a href="{base}cambios">Envíos y cambios</a><a href="{base}privacidad">Privacidad</a><a href="{base}terminos">Términos</a><a href="{HELLO}" target="_blank" rel="noopener">WhatsApp {ARROW}</a></div></div><div class="footer-brand" aria-hidden="true">BOLEM</div><div class="footer-bottom"><span>© 2026 BOLEM · El Salvador</span><span>Moda. Cercanía. Vos.</span></div></footer></body></html>'''
def write(path,s):
 p=OUT/path;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf-8')
def home():
 hero=BYID['vestido-cobalto'];second=BYID['vestido-maxi-smocked']
 picks=[BYID[x] for x in ['vestido-maxi-smocked','blusa-peplum-gingham','conjunto-burdeos','jeans-flare'] if x in BYID]
 if len(picks)<4:picks=[BYID[x] for x in ['vestido-maxi-smocked','chaleco-elegante-marfil','conjunto-burdeos','jeans-flare']]
 body=f'''<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="little-line"></span> DESDE EL SALVADOR</p><h1>Moda plus size<br><em>para lucirte.</em></h1><p class="hero-desc">Piezas elegidas pensando en vos.<br>Para llevarlas a tu manera.</p><a class="button button-ink" href="coleccion/">Descubrí la colección {ARROW}</a><p class="hero-note">Tallas XL a 4XL · Te asesoramos por WhatsApp</p></div><div class="hero-main"><a href="prendas/{hero['id']}" aria-label="Ver {E(hero['nombre'])}">{photo(hero,size='hero',eager=True)}</a><a class="hero-caption" href="prendas/{hero['id']}"><span>{hero['nombre']}<small>XL · 1XL · 2XL</small></span><span>{M(hero['precio'])} {ARROW}</span></a></div><div class="hero-aside"><div class="curve-mark" aria-hidden="true"><i></i><i></i></div><a class="aside-photo" href="prendas/{second['id']}">{photo(second)}<span>Un sí al blanco. {ARROW}</span></a><p>Elegidas con intención.<br>Para vivirlas a tu manera.</p></div></section><nav class="category-strip wrap" aria-label="Explorar por categoría">{chips()}</nav><section class="section wrap"><div class="section-heading"><div><p class="eyebrow">EL PRÓXIMO LOOK EMPIEZA ACÁ</p><h2>Encontrá tu <em>favorita.</em></h2></div><a class="text-link" href="coleccion/">Ver las {N} prendas {ARROW}</a></div><div class="product-grid">{''.join(card(p,i=i) for i,p in enumerate(picks))}</div></section><section class="size-story wrap"><div class="size-art" aria-hidden="true"><span class="shape-bar"></span><span class="shape-bowl"></span><span class="shape-circle"></span></div><div class="size-copy"><p class="eyebrow">ENCONTRAR TU TALLA, SIN ADIVINAR</p><h2>La etiqueta no<br>cuenta <em>todo.</em></h2><p>Una XL puede cambiar de una marca a otra. Contanos qué prenda te gustó y te ayudamos a elegir antes de pedirla.</p><a class="text-link" href="tallas">Hablemos de tallas {ARROW}</a></div></section><section class="section wrap story"><div><p class="eyebrow">DE MÓNICA, CON INTENCIÓN</p><h2>Elegir ropa.<br><em>Pensar en vos.</em></h2></div><div><p>Mónica creó BOLEM al ver a su mamá y a su hermana buscar ropa que les gustara y no encontrar su talla. Hoy, Mónica elige e importa piezas para que haya más opciones, más color y más ganas de vestirse.</p><a class="text-link" href="nosotras">Conocé nuestra historia {ARROW}</a></div></section><section class="club"><div class="wrap club-inner"><div><p class="eyebrow">CERQUITA DE BOLEM</p><h2>Que lo próximo<br>te encuentre <em>primero.</em></h2></div><div><p>Nuevas piezas y novedades de BOLEM, directo a tu WhatsApp.</p><a class="button button-ink" href="{wa('Hola, quiero recibir novedades y unirme a la lista VIP de BOLEM.')}" target="_blank" rel="noopener">Quiero ser parte {ARROW}</a><small>Se abre WhatsApp. Enviá el mensaje para unirte.</small></div></div></section>'''
 write('index.html',shell('Moda plus size para lucirte',body))
def collection():
 base='../'
 filters=''.join(f'<button type="button" class="filter-chip" data-filter="{k}" aria-pressed="false">{E(c["etiqueta"])} <span>{sum(p["categoria"]==k for p in PRODUCTS)}</span></button>' for k,c in CATS.items())
 body=f'''<header class="catalog-heading wrap"><p class="eyebrow">LA COLECCIÓN BOLEM</p><div><h1>¿Cuál va <em>con vos?</em></h1><p>{N} prendas. Muchas formas de llevarlas.</p></div></header><section class="wrap catalog-section" aria-label="Catálogo de prendas"><form class="catalog-controls js-only" id="catalog-filters"><div class="category-filters" role="group" aria-label="Categoría"><button type="button" class="filter-chip" data-filter="all" aria-pressed="true">Todas <span>{N}</span></button>{filters}</div><div class="filter-bottom"><label>Talla <select name="talla" aria-label="Filtrar por talla"><option value="">Todas las tallas</option>{''.join(f'<option>{s}</option>' for s in D['escala_tallas'])}</select></label><label>Ordenar <select name="orden" aria-label="Ordenar prendas"><option value="original">Orden del catálogo</option><option value="menor">Menor precio</option><option value="mayor">Mayor precio</option></select></label><button class="reset-filters" type="reset">Limpiar filtros</button></div></form><div class="catalog-count"><p id="result-count" role="status" aria-live="polite">{N} prendas</p><a href="../tallas">¿Dudas con tu talla? {ARROW}</a></div><noscript><p>Podés recorrer todas las prendas. Para combinar filtros, activá JavaScript.</p></noscript><div class="empty-state" id="empty-state" hidden><h2>Probemos con otra combinación.</h2><p>No hay prendas de esa categoría en la talla elegida.</p><button class="button button-outline" type="button" data-reset>Ver todas las prendas {ARROW}</button></div><div class="product-grid catalog-grid" id="catalog-grid">{''.join(card(p,base,i) for i,p in enumerate(PRODUCTS))}</div><div class="catalog-help"><h2>¿Te ayudamos a elegir?</h2><p>Contanos qué buscás. Te orientamos por WhatsApp.</p><a class="button button-ink" href="{HELLO}" target="_blank" rel="noopener">Hablemos {ARROW}</a></div></section>'''
 write('coleccion/index.html',shell('La colección',body,base,'col'))
def product(p):
 base='../'; f=p['fotos'][0];prefix='../../assets/productos/'
 initial=wa(f'Hola, me interesa {p["nombre"]} ({M(p["precio"])}), código {p["id"]}. ¿Me confirmás disponibilidad y me ayudás con la talla?')
 thumbs=''.join(f'<button type="button" class="thumbnail" aria-label="Ver foto {i+1} de {len(p["fotos"])}" aria-pressed="{str(i==0).lower()}" data-photo="{i}" data-full="{prefix}{name[:-5]}-800.webp" data-srcset="{prefix}{name[:-5]}-480.webp 480w, {prefix}{name[:-5]}-800.webp 800w, {prefix}{name} 1200w"><img src="{prefix}{name[:-5]}-480.webp" width="80" height="120" alt="" loading="lazy"></button>' for i,name in enumerate(p['fotos']))
 related=[q for q in PRODUCTS if q['categoria']==p['categoria'] and q['id']!=p['id']][:4]
 body=f'''<div class="wrap"><nav class="breadcrumbs" aria-label="Ruta de navegación"><a href="../">Inicio</a><span>/</span><a href="../coleccion/">Colección</a><span>/</span><a href="../coleccion/?categoria={p['categoria']}">{CATS[p['categoria']]['etiqueta']}</a></nav><article class="product-detail" data-id="{p['id']}" data-product-name="{E(p['nombre'])}" data-product-price="{M(p['precio'])}"><div class="detail-title"><p class="eyebrow">{CATS[p['categoria']]['etiqueta']}</p><h1>{E(p['nombre'])}</h1><p class="detail-price">{M(p['precio'])} <span>USD</span></p></div><div class="detail-gallery"><div class="main-photo" id="product-gallery">{photo(p,base,'hero',eager=True)}</div><div class="thumbnails js-only" aria-label="Fotos de la prenda">{thumbs}</div><noscript><div class="fallback-photos">{''.join(photo(p,base,index=i) for i in range(1,len(p['fotos'])))}</div></noscript><p class="image-caption">{p['colores']} {'color' if p['colores']==1 else 'colores'} · Consultá disponibilidad al escribirnos.</p></div><div class="detail-buy">{('<p class="detail-intro">'+E(p["descripcion"])+'</p>') if p.get("descripcion") else ""}<fieldset class="size-options"><legend>¿Qué talla buscás?</legend>{''.join(f'<label><input type="radio" name="size" value="{s}"><span>{s}</span></label>' for s in p['tallas'])}</fieldset><a href="../tallas" class="size-guide-link">No sé qué talla elegir {ARROW}</a><a href="{initial}" class="button button-ink product-wa" target="_blank" rel="noopener">{'Consultar reposición' if p.get('agotada') else 'Consultar por WhatsApp'} {ARROW}</a><p class="purchase-note">Te confirmamos talla, color y disponibilidad antes de apartar.</p><div class="delivery"><div><span aria-hidden="true">↗</span><p><strong>Envío a todo El Salvador</strong>$3.50 área metropolitana · $5 resto del país · De 1 a 3 días hábiles</p></div><div><span aria-hidden="true">✓</span><p><strong>Pagás al recibir</strong>Efectivo contra entrega o transferencia</p></div><div><span aria-hidden="true">↔</span><p><strong>Cambios de talla</strong><a href="../cambios">Dentro de los 2 días de recibido</a></p></div></div><details><summary>Sobre la talla y la tela <span aria-hidden="true">+</span></summary><p>Las etiquetas varían entre marcas. Preguntanos por las medidas, la tela y el ajuste de esta pieza; te orientamos antes de confirmar tu pedido.</p></details><details><summary>Cómo comprar <span aria-hidden="true">+</span></summary><p>Escribinos con la prenda y tu talla. Confirmamos disponibilidad, coordinamos el pago y la entrega, y te ayudamos si necesitás un cambio.</p></details><p class="sku">Referencia: {p['id']}</p></div></article><section class="section"><div class="section-heading"><div><p class="eyebrow">SEGUÍ EXPLORANDO</p><h2>Más para <em>vos.</em></h2></div><a class="text-link" href="../coleccion/?categoria={p['categoria']}">Ver {CATS[p['categoria']]['etiqueta'].lower()} {ARROW}</a></div><div class="product-grid">{''.join(card(q,base,i) for i,q in enumerate(related))}</div></section></div><div class="mobile-buy"><span>{M(p['precio'])}</span><a href="{initial}" class="button button-ink product-wa" target="_blank" rel="noopener">{'Consultar reposición' if p.get('agotada') else 'Consultar por WhatsApp'} {ARROW}</a></div>'''
 write(f'prendas/{p["id"]}.html',shell(p['nombre'],body,base,'col',f'{p["nombre"]} — {M(p["precio"])}. Tallas {", ".join(p["tallas"])}. Consultá disponibilidad y asesoría por WhatsApp.'))
def editorial(title,kicker,body,active='',path='',base=''):
 content=f'<header class="editorial-header wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1></header><div class="prose wrap">{body}</div>'
 write(path or active+'.html',shell(re.sub('<[^>]+>','',title),content,base,active))
def support():
 editorial('Tu talla merece<br><em>una buena conversación.</em>','GUÍA BOLEM',f'''<p class="lead">La etiqueta es un punto de partida. Lo que importa es cómo te queda a vos.</p><h2>XL y 1XL pueden ser diferentes</h2><p>En nuestro catálogo hay prendas que ofrecen ambas opciones. No las tomés como equivalentes automáticas: el corte y las medidas cambian según la marca.</p><h2>Antes de elegir, probá esto</h2><ol class="steps"><li><strong>Elegí una prenda que te quede bien.</strong><p>Usá una similar a la que querés comprar y colocala sobre una superficie plana.</p></li><li><strong>Medila sin estirar la tela.</strong><p>Tomá el ancho de busto, cintura o cadera según la pieza. Contanos si estás midiendo ancho plano o contorno completo.</p></li><li><strong>Compartinos las medidas por WhatsApp.</strong><p>Decinos qué prenda BOLEM te gustó. Te ayudamos a comparar antes de apartarla.</p></li></ol><div class="prose-callout"><h2>¿Ya tenés una favorita?</h2><p>Mandanos su nombre o una captura junto con tu duda de talla.</p><a class="button button-ink" href="{wa('Hola, necesito ayuda para elegir mi talla en una prenda BOLEM.')}" target="_blank" rel="noopener">Ayudame con mi talla {ARROW}</a></div><h2>Lo que conviene saber</h2><details><summary>¿Todas las prendas tienen las mismas tallas?<span>+</span></summary><p>No. Cada ficha muestra las tallas de esa pieza. Algunas incluyen L y otras llegan a 4XL.</p></details><details><summary>¿Publican medidas exactas de cada prenda?<span>+</span></summary><p>Todavía no tenemos una tabla de medidas para cada pieza. Consultanos por la que te interesa antes de comprar.</p></details><details><summary>¿Puedo cambiarla si no me queda?<span>+</span></summary><p>Podés solicitar cambio de talla dentro de los 2 días de recibirla, sin uso y con etiquetas, sujeto a disponibilidad. <a href="cambios">Leé la política completa.</a></p></details>''','size','tallas.html')
 editorial('Una forma más cercana<br>de <em>encontrarte.</em>','LA HISTORIA DE BOLEM',f'''<p class="lead">Todo empezó con dos mujeres muy importantes para Mónica: su mamá y su hermana.</p><p>Mientras ella encontraba ropa que le gustaba, ellas se topaban con opciones limitadas en su talla. Esa diferencia fue el punto de partida de BOLEM.</p><h2>Elegir también es una forma de cuidar</h2><p>Mónica Claros elige e importa ropa terminada. Busca piezas que amplíen las opciones para mujeres plus size en El Salvador, con una atención cercana para encontrar talla y estilo.</p><p>BOLEM combina moda, comodidad y una idea sencilla: la mujer es la protagonista. La ropa la acompaña.</p><div class="prose-callout"><p class="eyebrow">LA MUJER ES LA PROTAGONISTA</p><h2>Más opciones.<br>Más formas de ser <em>vos.</em></h2></div><h2>La conversación sigue</h2><p>Detrás de cada pedido hay una conversación. Podés preguntarnos por una pieza, una talla o cómo coordinar tu entrega. Estamos para ayudarte a elegir.</p><a class="button button-ink" href="{HELLO}" target="_blank" rel="noopener">Conversemos {ARROW}</a>''','about','nosotras.html')
 for slug in ['cambios','privacidad','terminos']:
  original=(ROOT/(slug+'.html')).read_text(encoding='utf-8')
  inner=re.search(r'<main\b[^>]*>(.*?)</main>',original,re.S).group(1)
  inner=re.sub(r'\sstyle="[^"]*"','',inner)
  inner=re.sub(r'<svg\b.*?</svg>','',inner,flags=re.S)
  inner=inner.replace('guia-de-tallas','tallas').replace('nosotros','nosotras')
  inner=re.sub(r'(target="_blank")(?!\srel=)',r'\1 rel="noopener"',inner)
  write(slug+'.html',shell({'cambios':'Envíos y cambios','privacidad':'Privacidad','terminos':'Términos'}[slug],'<div class="legal-page wrap">'+inner+'</div>'))
def journal():
 articles=[
 ('tallas-xl-1xl-plus-size','XL y 1XL: elegí con más información','TALLAS','vestido-maxi-smocked','En algunas prendas de BOLEM vas a encontrar XL y 1XL como opciones separadas. Por eso, la etiqueta por sí sola no alcanza para elegir.','Compará la pieza, no solo la etiqueta','Las tallas pueden variar entre marcas. Contanos qué prenda te gustó y compartinos las medidas de una similar que ya te quede bien. Antes de confirmar el pedido, te orientamos sobre la opción disponible.'),
 ('como-elegimos-la-ropa','Elegidas por Mónica, pensadas para vos','BOLEM','chaleco-elegante-marfil','BOLEM elige e importa ropa terminada. Nuestra selección empieza por ampliar las opciones para mujeres plus size en El Salvador.','Una selección que se conversa','Las fotos, el precio y las tallas de cada pieza están en el catálogo. Si querés saber más de su tela o de cómo queda, escribinos. Preferimos conversar sobre una prenda concreta y ayudarte a elegir.'),
 ('looks-plus-size-clima-calido','Ideas para vestirte a tu manera','ESTILO','conjunto-burdeos','Un conjunto que podés llevar junto o combinar por separado. Una blusa con tus jeans favoritos. Un vestido al que volvés porque te gusta cómo te sentís.','Empezá por lo que ya disfrutás usar','Mirá colores y combinaciones en las fotos de la colección. Si la frescura de la tela es importante para vos, consultanos por la composición y el ajuste de esa pieza antes de pedirla.'),
 ('guia-tallas-plus-size','Antes de elegir tu talla','TALLAS','jeans-flare','Una prenda que ya te queda bien puede ayudarte a elegir la siguiente. Comparar sus medidas es más útil que asumir que todas las etiquetas son iguales.','Una referencia hecha a tu medida','Colocá la prenda sobre una superficie plana y medila sin estirarla. Contanos si tus medidas son de ancho plano o de contorno, y cuál pieza del catálogo te interesa. Te ayudamos por WhatsApp.'),
 ('por-que-casi-no-existe-la-4xl','Encontrar opciones en 4XL','TALLAS','chaleco-elegante-marfil','No todas las prendas llegan a la misma talla. En BOLEM podés filtrar la colección para ver las piezas que incluyen 4XL.','Mirar lo que sí hay para vos','El filtro muestra las tallas del catálogo; la disponibilidad final se confirma al escribirnos. Consultá por la pieza que te guste para revisar su ajuste antes de apartarla.'),
 ('historia-bolem-moda-plus-size-el-salvador','La historia empieza en casa','BOLEM','vestido-cobalto','Mónica veía a su mamá y a su hermana buscar ropa que les gustara y encontrar pocas opciones en su talla. Esa experiencia familiar dio origen a BOLEM.','La mujer es la protagonista','Hoy Mónica elige e importa piezas para mujeres plus size en El Salvador. La atención personal sigue siendo parte de la experiencia: conversar sobre una talla, una prenda y lo que cada clienta busca.')]
 cards=[]
 for slug,title,tag,imgid,intro,sub,text in articles:
  p=BYID[imgid]
  cards.append(f'<article class="journal-card"><a href="{slug}">{photo(p,"../")}<p class="eyebrow">{tag}</p><h2>{title}</h2><span class="text-link">Leer la historia {ARROW}</span></a></article>')
  editorial(title,'DIARIO BOLEM · '+tag,f'<p class="lead">{intro}</p><h2>{sub}</h2><p>{text}</p><a class="text-link" href="../tallas">Nuestra guía de tallas {ARROW}</a><div class="prose-callout"><h2>Encontrá algo que te guste.</h2><a class="button button-ink" href="../coleccion/">Ver la colección {ARROW}</a></div>','blog','blog/'+slug+'.html','../')
 write('blog/index.html',shell('Diario BOLEM','<header class="editorial-header wrap"><p class="eyebrow">DIARIO BOLEM</p><h1>Moda, historias<br>y <em>conversaciones.</em></h1></header><section class="journal-grid wrap">'+''.join(cards)+'</section>','../','blog'))
home();collection();support();journal()
for p in PRODUCTS:product(p)
print(f'BOLEM v3: {len(list(OUT.rglob("*.html")))} páginas, {N} prendas. Fuente: _data/catalogo.json. Todas noindex.')
